'use strict';document.addEventListener('DOMContentLoaded',function(){var data=window.seopressPrimaryCategorySelectData;if(!data){return}
var taxonomies=data.taxonomies;if(!Array.isArray(taxonomies)||!taxonomies.length){return}
var nonceInjected=!1;taxonomies.forEach(function(taxonomy){if(!taxonomy||!taxonomy.selectHTML||!taxonomy.metaboxId||!taxonomy.fieldId){return}
var metabox=document.getElementById(taxonomy.metaboxId);if(!metabox){return}
var inside=metabox.querySelector('.inside');if(!inside){return}
if(inside.querySelector('#'+taxonomy.fieldId)){return}
var wrapper=document.createElement('div');wrapper.className='seopress-primary-category-wrapper';wrapper.innerHTML=taxonomy.selectHTML+(nonceInjected?'':data.nonceField||'');inside.appendChild(wrapper);nonceInjected=!0;var select=wrapper.querySelector('#'+taxonomy.fieldId);if(!select){return}
if(taxonomy.value){select.value=taxonomy.value}
var noneOption=select.querySelector('option[value="none"]').cloneNode(!0);var excluded=Array.isArray(taxonomy.excluded)?taxonomy.excluded.map(String):[];var checkboxSelector='input[type="checkbox"][name="'+taxonomy.checkboxName+'"]';function syncTerms(changedCheckbox){var previous=select.value;var terms=new Map();inside.querySelectorAll(checkboxSelector).forEach(function(checkbox){var label=checkbox.closest('label');if(checkbox.checked&&label){terms.set(checkbox.value,label.textContent.trim())}});if(changedCheckbox){if(changedCheckbox.checked){var label=changedCheckbox.closest('label');if(label){terms.set(changedCheckbox.value,label.textContent.trim())}}else{terms.delete(changedCheckbox.value)}}
excluded.forEach(function(id){terms.delete(id)});select.replaceChildren(noneOption.cloneNode(!0));terms.forEach(function(name,id){var option=document.createElement('option');option.value=id;option.textContent=name;select.appendChild(option)});select.value=terms.has(previous)?previous:'none'}
inside.addEventListener('change',function(event){if(event.target.matches(checkboxSelector)){syncTerms(event.target)}});new MutationObserver(function(records){if(records.some(function(record){return!wrapper.contains(record.target)})){syncTerms()}}).observe(inside,{childList:!0,subtree:!0});syncTerms()})})